use crate::{skin_package as package,skins::{Library,Request,Selection}};
use std::{path::PathBuf,fs};
use serde_json::{Value,json};
fn root()->PathBuf{let p=PathBuf::from(std::env::var_os("AI_GUILD_TEST_ROOT").expect("isolated test root")).join(format!("skins-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&p).unwrap();fs::write(p.join(".ai-guild-qa"),"OFFLINE only").unwrap();p}
fn fixture(name:&str)->Vec<u8>{fs::read(PathBuf::from(env!("CARGO_MANIFEST_DIR")).join(format!("../tests/fixtures/skin-packages/{name}.zip"))).unwrap()}
fn get(l:&Library)->Value{l.perform(Request::Get{legacy_theme:None}).unwrap()}
fn install(l:&Library)->Selection{let v=l.perform(Request::Import{bytes:fixture("blue-studio-test")}).unwrap();serde_json::from_value(v["installed"].clone()).unwrap()}
#[test]fn skin_package_valid_stored_and_deflated_complete_decode(){for f in ["blue-studio-test","blue-studio-deflated"]{let p=package::validate(&fixture(f)).unwrap();assert_eq!(p.manifest.skin_id,"blue-studio-test");assert_eq!(p.layout.characters.len(),2);assert_eq!(p.layout.assignments.len(),5);assert_eq!(p.animations.animations.len(),30);assert_eq!(p.locale.len(),2);}}
#[test]fn skin_package_rejects_all_adversarial_fixtures(){let cases:Vec<String>=serde_json::from_str(include_str!("../../tests/fixtures/skin-reject-cases.json")).unwrap();let mut outcomes=vec![];for case in cases{let error=package::validate(&fixture(&case)).expect_err(&case);outcomes.push(json!({"case":case,"error":error}));}fs::write(root().join("rejections.json"),serde_json::to_vec_pretty(&outcomes).unwrap()).unwrap();}
#[test]fn skin_package_paths_reject_windows_forms_and_nul(){for s in ["../a","/a","C:/x","//a/b","a\\b","a\0b","a:b","CON.txt","a/COM1.png","a/LPT9","a//b","a/./b","a/../b","a.","a ","AUX"]{assert!(package::safe_path(s).is_err(),"{s:?}")};assert!(package::safe_path("assets/sprites/a-1.png").is_ok());}
#[test]fn skin_package_archive_size_limit_before_zip_parse(){assert!(package::validate(&vec![0;package::MAX_ZIP+1]).unwrap_err().contains("ARCHIVE_SIZE"));}
#[test]fn skin_library_install_list_and_same_bytes_idempotent(){let r=root();let l=Library::new(&r);let s=install(&l);let v=get(&l);assert_eq!(v["entries"].as_array().unwrap().len(),3);assert_eq!(v["selected"]["skinId"],"builtin-paper");let again=install(&l);assert_eq!(s,again);assert_eq!(get(&l)["entries"].as_array().unwrap().len(),3);assert!(r.join("skins/blue-studio-test/1.0.0/package.zip").exists());}
#[test]fn skin_library_conflicting_version_rejected_and_existing_preserved(){let r=root();let l=Library::new(&r);let s=install(&l);let before=fs::read(r.join("skins/blue-studio-test/1.0.0/package.zip")).unwrap();assert!(l.perform(Request::Import{bytes:fixture("duplicate-id-version")}).unwrap_err().contains("CONFLICT"));assert_eq!(fs::read(r.join("skins/blue-studio-test/1.0.0/package.zip")).unwrap(),before);assert_eq!(install(&l),s);}
#[test]fn skin_library_selection_restored_by_fresh_instance(){let r=root();let l=Library::new(&r);let s=install(&l);let v=l.perform(Request::Select{selection:s.clone()}).unwrap();assert_eq!(v["selected"],json!(s));drop(l);let next=get(&Library::new(&r));assert_eq!(next["selected"],json!(s));assert!(next["render"].is_object());assert_eq!(next["render"]["layout"]["characters"].as_array().unwrap().len(),2);}
#[test]fn skin_library_legacy_mint_bridge_and_explicit_paper(){let r=root();let l=Library::new(&r);assert_eq!(l.perform(Request::Get{legacy_theme:Some("free-mint-test".into())}).unwrap()["selected"]["skinId"],"builtin-mint");assert_eq!(get(&l)["selected"]["skinId"],"builtin-mint");let v=l.perform(Request::Select{selection:Selection{skin_id:"builtin-paper".into(),version:"1.0.0".into(),package_sha256:"builtin:free-standard:v1".into()}}).unwrap();assert_eq!(v["selected"]["skinId"],"builtin-paper");}
#[test]fn skin_library_corruption_fallback_keeps_original_and_audit(){let r=root();let l=Library::new(&r);let s=install(&l);l.perform(Request::Select{selection:s.clone()}).unwrap();fs::write(r.join("skins/blue-studio-test/1.0.0/files/assets/sprites/planner.png"),"corrupt").unwrap();let v=get(&l);assert_eq!(v["selected"]["skinId"],"builtin-paper");assert!(v["fallbackReason"].is_string());assert_eq!(v["entries"][2]["state"],"CORRUPT");let audit=fs::read_to_string(r.join("presentation/skin-incidents.jsonl")).unwrap();assert!(audit.contains(&s.package_sha256));assert!(audit.contains("INSTALLED_HASH"));assert_eq!(get(&Library::new(&r))["selected"]["skinId"],"builtin-paper");assert!(fs::read_to_string(r.join("presentation/skin-incidents.jsonl")).unwrap().contains(&s.package_sha256));}
#[test]fn skin_library_missing_package_fallback(){let r=root();let l=Library::new(&r);let s=install(&l);l.perform(Request::Select{selection:s}).unwrap();fs::rename(r.join("skins/blue-studio-test/1.0.0/package.zip"),r.join("missing-package.zip")).unwrap();assert_eq!(get(&l)["selected"]["skinId"],"builtin-paper");}
#[test]fn skin_library_staging_and_failed_install_are_not_selectable(){let r=root();fs::create_dir_all(r.join("skins/.staging-interrupted/files")).unwrap();fs::write(r.join("skins/.staging-interrupted/files/manifest.json"),"partial").unwrap();let l=Library::new(&r);assert!(l.perform(Request::Import{bytes:fixture("corrupt-png")}).is_err());assert_eq!(get(&l)["entries"].as_array().unwrap().len(),2);let s=Selection{skin_id:"not-installed".into(),version:"1.0.0".into(),package_sha256:"0".repeat(64)};assert!(l.perform(Request::Select{selection:s}).is_err());}
#[test]fn skin_library_renderer_fallback_is_selection_bound(){let r=root();let l=Library::new(&r);let s=install(&l);l.perform(Request::Select{selection:s.clone()}).unwrap();let v=l.perform(Request::Fallback{selection:s,reason:"SKIN_RENDERER_EXCEPTION".into()}).unwrap();assert_eq!(v["selected"]["skinId"],"builtin-paper");assert!(fs::read_to_string(r.join("presentation/skin-incidents.jsonl")).unwrap().contains("RENDERER_FALLBACK"));}
#[test]fn skin_library_local_hardlink_is_rejected_without_reading_target(){let r=root();let l=Library::new(&r);let s=install(&l);l.perform(Request::Select{selection:s}).unwrap();let file=r.join("skins/blue-studio-test/1.0.0/files/NOTICES");fs::hard_link(&file,r.join("other-link")).unwrap();assert_eq!(get(&l)["selected"]["skinId"],"builtin-paper");}
#[test]fn skin_library_semantic_core_state_and_artifact_unchanged(){
 use crate::{engine::Engine,core_api::{self,Action},rpc::Rpc,setup::Settings,purposes};use std::{sync::atomic::Ordering,time::{Instant,Duration}};
 let r=root();fs::create_dir_all(r.join("output")).unwrap();let e=Engine::open(&r,None).unwrap();e.save_setup(Settings{work_root:r.to_string_lossy().into(),output_root:r.join("output").to_string_lossy().into(),approval_policy:"on-request".into(),..Default::default()}).unwrap();
 fs::write(r.join("offline-plan.json"),json!({"title":"OFFLINE S4","requirements":["小さく始める"],"checklist":["原文を保持"],"files":[{"name":"post.txt","requiredText":["小さく始める"]}]}).to_string()).unwrap();fs::write(r.join("offline-event.html"),json!({"files":[{"name":"post.txt","content":"小さく始める。\nOFFLINE S4 fixture\n"}]}).to_string()).unwrap();*e.rpc.lock().unwrap()=Some(Rpc::phase9_fixture(&r).unwrap());e.update(|s|{s.connection.status="connected".into();Ok(())}).unwrap();
 let job=core_api::start_prepared_purpose(&e,purposes::prepare(purposes::SOCIAL,purposes::PRIOR_VERSION,json!({"theme":"小さく始める","contentLanguage":"ja"})).unwrap(),None).unwrap();let end=Instant::now()+Duration::from_secs(20);while e.worker.load(Ordering::SeqCst)&&Instant::now()<end{std::thread::sleep(Duration::from_millis(20))}assert!(!e.worker.load(Ordering::SeqCst));let snapshot=e.snapshot();assert_eq!(snapshot.job.as_ref().unwrap().status,"awaiting_approval");
 let before=serde_json::to_value(&snapshot).unwrap();let db_before=fs::read(r.join("guild.sqlite3")).unwrap();let artifact=snapshot.job.as_ref().unwrap().artifacts.iter().find(|a|a.name=="post.txt").unwrap();let text_before=package::hash(&fs::read(&artifact.path).unwrap());let presentation=e.presentation_snapshot(job["jobId"].as_str().unwrap()).unwrap();
 let l=Library::new(&r);let s=install(&l);l.perform(Request::Select{selection:s}).unwrap();get(&l);l.perform(Request::Select{selection:Selection{skin_id:"builtin-mint".into(),version:"1.0.0".into(),package_sha256:"builtin:free-mint-test:v1".into()}}).unwrap();
 assert_eq!(serde_json::to_value(e.snapshot()).unwrap(),before);assert_eq!(fs::read(r.join("guild.sqlite3")).unwrap(),db_before);assert_eq!(package::hash(&fs::read(&artifact.path).unwrap()),text_before);assert_eq!(e.presentation_snapshot(job["jobId"].as_str().unwrap()).unwrap(),presentation);
 fs::write(r.join("core-invariance.json"),serde_json::to_vec_pretty(&json!({"result":"PASS","before":before,"after":e.snapshot(),"artifactSha256":text_before,"dbSameBytes":true,"scope":"isolated real Engine/SQLite with offline peer, no real inference"})).unwrap()).unwrap();e.get_rpc().unwrap().shutdown();
}
